import { b, type Bilingual } from './core';
export type ExperimentStep={action:Bilingual;result:Bilingual};
export type ExperimentGuide={objective:Bilingual;limit:Bilingual;steps:ExperimentStep[]};
const s=(actionPt:string,actionEn:string,resultPt:string,resultEn:string):ExperimentStep=>({action:b(actionPt,actionEn),result:b(resultPt,resultEn)});

// Instructions name actual controls; advancing this guide never operates the desk.
export const experimentGuides:Record<string,ExperimentGuide>={
m24:{objective:b('Comparar contenção, preservação e retorno com critérios; descobrir por que o portal abrir não basta.','Compare containment, preservation and criteria-based return; discover why opening the portal is insufficient.'),limit:b('Caso fixo fictício sem EDR, coleta ou sistemas reais. O bloqueio representa critérios didáticos deste caso, não uma ordem universal para incidentes.','Fixed fictional case with no EDR, collection or real systems. Blocking represents educational criteria for this case, not a universal incident sequence.'),steps:[
s('Clique Liberar retorno antes de qualquer ação. Leia o bloqueio e identifique os critérios pendentes.','Click Release return before any action. Read the block and identify pending criteria.','O portal permanece fora de produção. Disponibilidade não prova recuperação; o modelo exige contenção, preservação, correção e teste.','The portal remains out of production. Availability does not prove recovery; the model requires containment, preservation, correction and testing.'),
s('Clique Conter estação e depois Testar recuperação. Compare a estação isolada com a sessão cloud ainda ativa. Em seguida preserve os registros.','Click Contain workstation then Test recovery. Compare the isolated workstation with the still-active cloud session. Then preserve records.','Contenção limita um caminho, mas não revoga a sessão. O teste falha. Preservar registra origem, horário, coletor e integridade; poderia ter sido feito antes da contenção neste modelo.','Containment limits one path but does not revoke the session. The test fails. Preservation records source, time, collector and integrity; it could precede containment in this model.'),
s('Use Tratar causa e acessos, Testar recuperação e Liberar retorno. Leia cada resultado; reinicie e compare preservação antes de contenção.','Use Address cause and access, Test recovery and Release return. Read each result; reset and compare preservation before containment.','O retorno ocorre só após os critérios. O teste inclui função, dados e rejeição da sessão antiga; a aprovação e o monitoramento continuam necessários. A ordem de coleta e contenção varia com risco real.','Return occurs only after criteria pass. Testing includes function, data and rejection of the old session; approval and monitoring remain necessary. Collection and containment order varies with real risk.') ]},

 m23:{objective:b('Ler as duas direções, distinguir metadados de conteúdo e comparar uma transferência sem finalidade confirmada com um backup autorizado.','Read both directions, distinguish metadata from content and compare a transfer without confirmed purpose against approved backup.'),limit:b('Oito resumos fixos e fictícios em uma janela de 60 segundos. Não executa Wireshark, captura pacotes ou descriptografa TLS. Desligar a coleta simula outra janela sem dados; religar restaura exemplos, não recupera tráfego real perdido.','Eight fixed fictional summaries in a 60-second window. It does not run Wireshark, capture packets or decrypt TLS. Turning collection off simulates another window without data; restoring it restores examples, not real lost traffic.'),steps:[
 s('Selecione “Consulta DNS” em Conversa de teste, leia IPs, portas, UDP e bytes. Depois escolha “Portal escolar” e compare TCP/TLS. Mantenha a coleta ligada e o filtro nos dois sentidos.','Select “DNS lookup” under Test conversation and read IPs, ports, UDP and bytes. Then choose “School portal” and compare TCP/TLS. Keep collection on and the filter in both directions.','Os campos têm funções diferentes. O protocolo foi identificado pelo sensor fictício; a porta isolada não o comprova. Cada linha soma bytes de uma direção durante 60 s, não é um pacote.','Fields have different roles. The fictional sensor identified the protocol; a port alone does not prove it. Each row totals one direction’s bytes across 60 s; it is not a packet.'),
 s('No Portal escolar, escolha “Somente origem na estação”. Observe uma linha. Troque para “Somente destino” e depois “origem OU destino”. Compare endereços, portas e o contador.','On School portal, select “Workstation source only”. Observe one row. Switch to “Workstation destination only”, then “source OR destination”. Compare addresses, ports and the counter.','A resposta do servidor tem origem .20:443 e destino .25:51514. O filtro amplo volta a mostrar duas linhas; ele revelou dados ocultos, sem criar nem apagar registros.','The server reply has source .20:443 and destination .25:51514. The broad filter shows two rows again; it reveals hidden data without creating or deleting records.'),
 s('Selecione “Transferência a investigar”, nos dois sentidos, e leia o volume e os limites TLS. Compare com “Backup com chamado”. Confira a caixa B-17 e volte à transferência. Explique por que somente um caso foi autorizado.','Select “Transfer to investigate”, in both directions, and read volume and TLS limits. Compare “Backup with ticket”. Check B-17 and return to the transfer. Explain why only one case was authorized.','Ambos enviam 8 MB na mesma janela, mas B-17 cobre apenas estação .30, destino .40 e aquele backup. O outro fluxo continua a investigar. Sem conteúdo descriptografado, não se pode afirmar qual arquivo foi enviado.','Both send 8 MB in the same window, but B-17 covers only workstation .30, destination .40 and that backup. The other flow still needs investigation. Without decrypted content, the sent file cannot be identified.'),
 s('Desmarque “Coleta funcionando nesta janela”. Leia “não avaliável” e tente mudar o filtro: o resultado não volta. Religue a coleta e formule um relato com janela, sensor, filtro e pergunta ainda pendente.','Clear “Collection working in this window”. Read “cannot assess” and try changing the filter: results do not return. Restore collection and formulate a report with window, sensor, filter and remaining question.','O filtro não substitui dados ausentes. Registre a lacuna e busque fontes complementares; preserve registros anteriores. Nesta simulação religar restaura o conjunto fixo, não reconstrói um período real perdido.','A filter does not replace missing data. Record the gap and seek complementary sources; preserve earlier records. In this simulation restoring collection restores the fixed dataset, not a real lost period.') ]},
 m1:{objective:b('Descobrir como uma senha vazada na loja pode afetar o e-mail e qual caminho cada camada ajuda a interromper.','Discover how a leaked shop password may affect email and which path each layer helps interrupt.'),limit:b('As caixas representam decisões já aplicadas. Nenhuma senha é criada, trocada ou testada; MFA não é uma garantia contra todo ataque.','Checkboxes represent applied decisions. No password is created, changed or tested; MFA does not guarantee protection from every attack.'),steps:[
 s('Deixe as três caixas desmarcadas. Leia a ligação entre loja e e-mail. Antes de ativar algo, explique por que o vazamento de uma conta poderia atingir outra.','Clear all three boxes. Read the shop–email connection. Before enabling anything, explain why one account’s breach might affect another.','A mesma senha permite tentar a credencial em outro serviço. O risco se propaga pela reutilização, não porque o e-mail e a loja sejam o mesmo sistema.','The same password allows trying the credential at another service. Risk spreads through reuse, not because email and shop are one system.'),
 s('Ative somente “Gerenciador protegido”. Depois ative “Senhas exclusivas”. Compare a senha indicada no cartão do e-mail em cada situação.','Enable only “Protected password manager”, then “Unique passwords”. Compare the password shown on the email card in each state.','O gerenciador ajuda a manter senhas diferentes, mas não troca a vazada sozinho. A exclusividade é que muda a relação entre as credenciais neste exemplo.','A manager helps maintain different passwords but does not replace a leaked one itself. Uniqueness changes the relationship between credentials here.'),
 s('Ative MFA. Depois desmarque e remarque a exclusividade mantendo MFA ligado. Leia quais camadas continuam presentes e quais riscos ainda exigem cuidado.','Enable MFA, then clear and re-enable uniqueness while leaving MFA on. Read which layers remain and which risks still require care.','MFA acrescenta outra categoria de prova; não apaga o vazamento. Senhas exclusivas e MFA se complementam. Pedidos inesperados de aprovação e de códigos ainda podem ser golpes.','MFA adds another proof category; it does not erase the breach. Unique passwords and MFA complement each other. Unexpected approval or code requests can still be scams.') ]},
 m2:{objective:b('Distinguir pistas fracas de pedidos perigosos e escolher uma confirmação que não dependa da mensagem suspeita.','Distinguish weak clues from dangerous requests and choose verification independent of the suspicious message.'),limit:b('Uma mensagem fictícia ensina o raciocínio. Não há análise automática de e-mail real nem um detalhe isolado que determine todos os golpes.','A fictional message teaches reasoning. There is no real email analysis or single detail identifying every scam.'),steps:[
 s('Toque no remetente e depois na saudação. Compare o domínio recebido com entregas.example, a transportadora conhecida neste cenário.','Tap the sender, then the greeting. Compare the received domain with entregas.example, this scenario’s known carrier.','O nome pode ser copiado e o domínio é diferente do esperado. “Olá, cliente” também aparece em mensagens legítimas; a saudação sozinha não confirma fraude.','The name can be copied and the domain differs from the expected one. “Hello, customer” also appears in legitimate messages; the greeting alone does not confirm fraud.'),
 s('Toque no prazo de dez minutos e no pedido de código. Pense no que aconteceria se esse código fosse usado para entrar na sua conta.','Tap the ten-minute deadline and code request. Think about what would happen if that code were used to sign in to your account.','A urgência reduz seu tempo de conferência; o código pode completar um acesso indevido. Não envie o código para “testar” o remetente.','Urgency reduces verification time; the code may complete unauthorized access. Do not send it to “test” the sender.'),
 s('Releia os quatro trechos e formule seu próximo passo: abrir o app da transportadora já conhecido ou responder ao aviso? Justifique sem se apoiar no logo.','Reread all four parts and choose a next step: open the known carrier app or reply to the notice? Explain without relying on its logo.','O app conhecido permite conferir a entrega por um caminho independente. Responder ou usar o contato da mensagem mantém sua verificação sob controle do possível impostor.','The known app verifies delivery independently. Replying or using the message’s contact leaves verification under the possible impersonator’s control.') ]},
 m3:{objective:b('Localizar o host verdadeiro e separar proteção da conexão, confiança no pedido e registros locais do navegador.','Locate the actual host and separate connection protection, request trust and local browser records.'),limit:b('São três endereços fixos, sem navegação real. A caixa de modo anônimo só representa seu efeito; não altera o navegador.','These are three fixed addresses without real navigation. The private-mode checkbox only represents its effect; it does not alter your browser.'),steps:[
 s('Selecione Exemplo 1. Identifique o host destacado e separe /login, o caminho. O serviço conhecido é nexus.example.','Select Example 1. Identify the highlighted host and separate /login, the path. The known service is nexus.example.','conta.nexus.example é subdomínio do serviço conhecido neste inventário. Isso combina com o destino esperado, mas ainda é preciso avaliar o pedido.','conta.nexus.example is a subdomain of the known service in this inventory. It fits the expected destination, but the request still needs assessment.'),
 s('Compare Exemplos 2 e 3. Localize onde aparece “nexus.example”: à esquerda do domínio ou depois da barra? Observe se isso muda o host real.','Compare Examples 2 and 3. Locate “nexus.example”: left of the domain or after the slash? Observe whether it changes the actual host.','Nos dois casos o destino pertence a suporte.example. Um nome conhecido no subdomínio ou no caminho não transforma o endereço no serviço conhecido.','Both destinations belong to suporte.example. A familiar name in a subdomain or path does not turn the address into the known service.'),
 s('No Exemplo 3, ative e desative o modo anônimo. Confira se o endereço muda. Explique por que HTTPS e modo anônimo não corrigem esse destino.','In Example 3, turn private mode on and off. Check whether the address changes. Explain why HTTPS and private mode do not fix the destination.','O host permanece igual. HTTPS protege o trânsito até ele; modo anônimo reduz registros locais. Nenhum dos dois confirma que aquele pedido vem da NEXUS.','The host stays the same. HTTPS protects transit to it; private mode reduces local records. Neither confirms that the request comes from NEXUS.') ]},
 m4:{objective:b('Atender à entrega do livro com dados suficientes, retirando os que não têm relação com a finalidade descrita.','Complete book delivery with sufficient data while removing fields unrelated to the stated purpose.'),limit:b('A necessidade dos campos é fornecida por este cenário. Outros serviços exigem análise própria; o contador não mede conformidade com a LGPD.','Field requirements are supplied by this scenario. Other services need separate assessment; the counter does not measure LGPD compliance.'),steps:[
 s('Comece com os quatro campos marcados. Para cada um, diga como ajudaria a entregar o livro. Não use a quantidade sozinha para decidir.','Start with all four fields selected. Explain how each helps deliver the book. Do not decide by count alone.','Nome e endereço atendem à entrega definida. Documento e cor favorita não têm necessidade descrita; quatro campos aumentam a exposição sem melhorar essa tarefa.','Name and address support the defined delivery. ID and favorite color have no described need; four fields increase exposure without improving this task.'),
 s('Retire a foto do documento e a cor favorita. Leia o feedback e veja se a finalidade ainda pode ser atendida.','Remove the ID photo and favorite color. Read feedback and check whether the purpose can still be met.','Dois campos continuam suficientes neste cenário. Minimização é manter o necessário com menos exposição; não é buscar sempre o menor número possível.','Two fields remain sufficient here. Minimization means keeping necessary data with less exposure, not always seeking the smallest possible number.'),
 s('Retire também o endereço. Compare o feedback com a etapa anterior e depois recoloque-o. Qual informação seria diferente se a tarefa fosse retirada na loja?','Also remove the address. Compare feedback with the previous step, then restore it. What would differ if the task were in-store pickup?','Sem endereço falta um dado necessário à entrega. Outra finalidade pode mudar os campos exigidos; justifique cada pedido pela tarefa real, não por hábito.','Without an address, delivery lacks necessary data. A different purpose may change required fields; justify each request by the actual task rather than habit.') ]},
 m5:{objective:b('Relacionar contenção, comunicação, análise e recuperação, entendendo por que uma ação isolada não resolve todo o incidente.','Connect containment, communication, analysis and recovery, understanding why one action cannot resolve the whole incident.'),limit:b('A sequência é um plano simplificado da NEXUS. Em incidentes reais, responsáveis e ordem dependem do plano; o jogo não isola nem restaura seu computador.','The sequence is a simplified NEXUS plan. Actual roles and order depend on the real plan; the game neither isolates nor restores your computer.'),steps:[
 s('Antes de iniciar, tente “Restaurar com a equipe”. Depois teste “Apagar todos os registros”. Leia por que o modelo recusa essas escolhas agora.','Before starting, try “Restore with the team”, then “Delete all logs”. Read why the model rejects these choices now.','Restaurar exige validações anteriores. Apagar registros destrói contexto útil à investigação. Não confunda acabar com o alerta visível com tratar o problema.','Restoring requires earlier checks. Deleting logs destroys useful investigation context. Removing a visible warning is not the same as addressing the problem.'),
 s('Escolha isolar conforme o plano e, em seguida, registrar e avisar. Observe as etapas concluídas e o que ainda falta antes de recuperar.','Choose isolation under the plan, then recording and notification. Observe completed stages and what remains before recovery.','O isolamento limita caminhos de propagação; o relato permite à equipe investigar. Nenhuma dessas ações confirma que o ambiente ou a cópia já estejam adequados.','Isolation limits spread paths; reporting enables team investigation. Neither action confirms that the environment or copy is already suitable.'),
 s('Selecione a validação de ambiente e cópia, depois a restauração. Recomece e teste a opção de pagamento para comparar seu limite.','Select environment and copy validation, then restoration. Restart and test the payment option to compare its limitation.','A recuperação ocorre após tratar a causa e validar os recursos neste plano. Pagamento não garante recuperar arquivos; retomar exige acompanhamento, não apenas fechar o aviso.','Recovery follows addressing the cause and validating resources under this plan. Payment does not guarantee file recovery; resumption needs monitoring, not just closing the warning.') ]},
 m6:{objective:b('Conceder acesso conforme a função usada, sem deixar recursos extras liberados apenas porque pertencem ao mesmo app.','Grant access according to the feature in use without leaving extra resources enabled merely because they belong to the same app.'),limit:b('O modelo tem duas funções e quatro permissões fixas. Não altera seu celular nem representa todas as opções de Android ou iOS.','The model has two fixed features and four permissions. It does not alter your phone or represent every Android or iOS option.'),steps:[
 s('Selecione “Digitar uma nota” e deixe todas as permissões desligadas. Leia se essa tarefa depende da câmera.','Select “Type a note” and clear all permissions. Read whether the task depends on camera access.','Digitar não exige câmera, contatos, localização ou microfone nas funções descritas. A finalidade do app não justifica automaticamente qualquer acesso.','Typing needs none of camera, contacts, location or microphone in the described features. The app’s purpose does not automatically justify any access.'),
 s('Mude para “Fotografar uma nota”. Observe o que falta; depois libere somente câmera. Compare o feedback antes e depois.','Switch to “Photograph a note”. Observe what is missing, then allow only camera. Compare feedback before and after.','Sem câmera a função de foto não funciona; com câmera ela recebe o recurso necessário. Menor privilégio deve permitir a tarefa, não simplesmente negar tudo.','Without camera access the photo feature cannot work; with it the feature receives its necessary resource. Least privilege should enable the task rather than deny everything.'),
 s('Ative contatos e localização. Veja os acessos extras e retire-os. Volte a digitar mantendo câmera ligada: ela ainda é necessária?','Enable contacts and location. Observe extra access and remove it. Return to typing with camera still enabled: is it still needed?','Os acessos extras não atendem à função descrita. Ao voltar para texto, câmera também deixa de ser necessária nesta tarefa. Revise permissões quando o uso mudar.','Extra access does not serve the described feature. Returning to text also removes the task’s camera need. Review permissions when usage changes.') ]},
 m7:{objective:b('Comparar sobrevivência das cópias e capacidade de recuperação; preservar uma versão e conseguir restaurá-la são verificações diferentes.','Compare copy survival and recovery capability: preserving a version and being able to restore it are different checks.'),limit:b('Não ocorre restauração real. A caixa representa o resultado fornecido de um teste; nenhuma cópia, arquivo ou chave do seu dispositivo é acessada.','No real restoration occurs. The checkbox represents a supplied test outcome; no device copy, file or key is accessed.'),steps:[
 s('Use “Reiniciar”, deixe o teste desmarcado e simule exclusão. Compare a pasta sincronizada sem histórico com as cópias anteriores.','Use Reset, leave the test box clear and simulate deletion. Compare the synced folder without history with earlier copies.','A exclusão replica na pasta sincronizada. As cópias anteriores permanecem neste caso, mas sua existência ainda não demonstra que os arquivos possam ser abertos.','Deletion replicates to the synced folder. Earlier copies remain here, but their existence does not demonstrate that files can be opened.'),
 s('Simule ransomware. Compare o disco conectado e gravável com a cópia desconectada. Explique qual caminho de alteração foi interrompido.','Simulate ransomware. Compare the connected writable disk with the disconnected copy. Explain which alteration path was interrupted.','Neste ataque, recursos graváveis são atingidos; a cópia desconectada fica fora desse caminho. Isso não comprova sua integridade, atualidade ou posse da chave necessária.','In this attack, writable resources are affected; the disconnected copy remains outside that path. This does not establish integrity, freshness or possession of a necessary key.'),
 s('Marque “Simular resultado: restauração testada com sucesso”. Compare o novo feedback. Que trabalho seria necessário para obter esse resultado fora do jogo?','Select “Simulate outcome: restoration successfully tested”. Compare the new feedback. What work would be needed to obtain this result outside the game?','A caixa fornece um resultado hipotético; não realiza o teste. Na prática, restaure em local apropriado, abra os arquivos e confira versões, chaves e dependências. Repita periodicamente.','The box supplies a hypothetical result; it does not run a test. In practice, restore in an appropriate location, open files and check versions, keys and dependencies. Repeat periodically.') ]},
 m8:{objective:b('Seguir a consulta DNS até o destino e verificar o serviço, mudando uma variável por vez para entender a divergência.','Follow a DNS lookup to its destination and check the service, changing one variable at a time to understand differences.'),limit:b('IPs e respostas são fictícios e fixos. Não há consulta DNS, conexão ou certificado real; outros destinos e portas exigem contexto próprio.','IPs and responses are fixed fictional data. There is no actual DNS lookup, connection or certificate; other destinations and ports need their own context.'),steps:[
 s('Selecione resolvedor aprovado e porta 443. Acompanhe estação, DNS, destino retornado e serviço. Compare com o inventário descrito acima da bancada.','Select approved resolver and port 443. Follow workstation, DNS, returned destination and service. Compare against the inventory above the desk.','O DNS consultado e o destino são endereços distintos. A resposta 192.0.2.20 e HTTPS/443 combinam com o inventário deste caso, sem provar confiança completa.','The queried DNS server and destination have different addresses. Response 192.0.2.20 and HTTPS/443 match this case’s inventory without proving complete trust.'),
 s('Mantenha o resolvedor aprovado e troque só a porta para 53. Qual parte do caminho continua igual e por que a página não é entregue?','Keep the approved resolver and change only the port to 53. Which path portion stays the same, and why is the page not delivered?','O destino continua correto, mas o serviço selecionado não é o HTTPS esperado. Chegar ao IP não equivale a acessar o serviço desejado.','The destination remains correct, but the selected service is not expected HTTPS. Reaching the IP is not the same as accessing the desired service.'),
 s('Volte a 443 e troque só o resolvedor para não aprovado. Depois teste 53 nesse estado e compare as explicações.','Return to 443 and change only the resolver to unapproved. Then test 53 in that state and compare explanations.','A resposta muda para 203.0.113.80. O cenário fornece divergência de certificado na tentativa HTTPS; com 53, o problema é outro serviço e destino divergente. Não ignore alertas para continuar.','The answer changes to 203.0.113.80. The scenario supplies a certificate mismatch for HTTPS; with 53 the problem is a different service and unexpected destination. Do not bypass warnings to continue.') ]},
 m9:{objective:b('Escolher entre confidencialidade, comparação de bytes e verificação de assinatura, acompanhando o papel de cada chave.','Choose between confidentiality, byte comparison and signature verification while following each key’s role.'),limit:b('A cifra é insegura e didática; hashes são referências pré-calculadas. O diagrama não gera chaves nem executa AES, RSA ou assinatura real.','The cipher is insecure and educational; hashes are precomputed references. The diagram does not generate keys or perform AES, RSA or real signing.'),steps:[
 s('Em “Cifra de letras”, mude o deslocamento de 3 para outro valor e depois volte a 3. Compare RECEBIDO e LEITURA.','In “Letter cipher”, change the shift from 3 to another value, then return to 3. Compare RECEIVED and READING.','Recebido fica fixo; mudar a tentativa muda a leitura. Três desfaz a transformação usada. Só 26 possibilidades permitem tentativa exaustiva: não use essa cifra para proteger dados.','Received remains fixed; changing the attempted shift changes the reading. Three reverses the original transformation. Only 26 choices allow exhaustive guessing: do not use this cipher to protect data.'),
 s('Em “Hash do arquivo”, compare “Texto original” com “Alterar um caractere”. Leia os textos e compare o resumo inteiro, não apenas o começo.','In “File hash”, compare “Original text” and “Change one character”. Read the texts and compare the whole digest rather than just its beginning.','A versão 2 muda para 3; o resumo muda e mantém 64 caracteres hexadecimais. Isso mostra diferença de bytes, não se o arquivo é seguro; a referência também precisa ser confiável.','Version 2 changes to 3; the digest changes but stays 64 hexadecimal characters long. This shows different bytes, not file safety; the reference must also be trustworthy.'),
 s('Em “Caminho das chaves”, compare cifragem simétrica e assimétrica. Nova envia a Orion: diga de quem é cada chave antes de ler a observação.','In “Key path”, compare symmetric and asymmetric encryption. Nova sends to Orion: identify each key’s owner before reading the observation.','Simétrica usa um segredo compartilhado. No modelo assimétrico, Nova cifra para Orion com a pública dele; Orion usa sua privada. Não se usa automaticamente a pública de quem envia.','Symmetric encryption uses a shared secret. In the asymmetric model, Nova encrypts for Orion using his public key; Orion uses his private key. The sender’s public key is not automatically the one used.'),
 s('Selecione “Assinatura digital” e desmarque a associação confiável da chave pública. Compare o conteúdo visível e o problema de identidade.','Select “Digital signature” and clear trusted public-key identity binding. Compare visible content and the identity problem.','Nova assina com sua privada; Orion verifica com a pública de Nova. O texto não fica oculto. Sem associação confiável, a coerência matemática não confirma a identidade esperada.','Nova signs with her private key; Orion verifies with Nova’s public key. Text is not hidden. Without trusted binding, mathematical consistency does not confirm the expected identity.') ]},
 m10:{objective:b('Relacionar identidade, classe de permissão e ação, distinguindo acesso ao arquivo de pedidos de elevação.','Connect identity, permission class and action while distinguishing file access from elevation requests.'),limit:b('O Linux usa bits básicos de um arquivo, sem ACLs ou privilégios especiais. A parte Windows não implementa UAC nem altera seu sistema.','Linux uses basic bits for one file without ACLs or special privileges. The Windows section neither implements UAC nor alters your system.'),steps:[
 s('Na parte Linux, use “640”. Teste leitura e gravação com Nova, Orion e visitante. Confira qual classe corresponde a cada identidade.','In Linux, use “640”. Test read and write as Nova, Orion and visitor. Check the class corresponding to each identity.','Nova usa dono: lê e grava. Orion usa grupo: lê, mas não grava. Visitante usa outros: não tem esses acessos. Os bits são avaliados por classe.','Nova uses owner: read and write. Orion uses group: read, not write. Visitor uses others: neither access. Bits are evaluated by class.'),
 s('Use o exemplo “040”. Teste leitura como Nova e depois como Orion. Antes de testar, preveja se a leitura do grupo poderia compensar a falta do dono.','Use example “040”. Test reading as Nova, then Orion. Before testing, predict whether group read could compensate for missing owner read.','Nova é dona e recebe a classe do dono, sem leitura; não soma a classe do grupo. Orion usa grupo e lê. “Pertence à equipe” não basta para ignorar a regra aplicável.','Nova is owner and gets the owner class without read; she does not add the group class. Orion uses group and reads. “Belongs to the team” does not override the applicable rule.'),
 s('Na parte Windows, compare o atualizador verificado e o instalador inesperado. Experimente aprovar ou cancelar e leia finalidade e origem.','In Windows, compare the verified updater and unexpected installer. Try approving or canceling and read purpose and source.','Privilégio maior só se justifica pela tarefa esperada e origem conferida. Um pedido de elevação não é um selo de segurança; conceder acesso a algo desconhecido pode ampliar o dano.','Higher privilege needs an expected task and verified source. An elevation request is not a safety seal; granting unknown software access may expand harm.') ]},
 m11:{objective:b('Ler e filtrar um arquivo fictício com alvo claro e entender como ordem e falha alteram uma sequência de script.','Read and filter a fictional file with a clear target and understand how ordering and failure alter a script sequence.'),limit:b('Só comandos e blocos conhecidos são simulados. Não há acesso a arquivos reais nem execução de PowerShell; clicar num exemplo preenche o campo, depois é preciso enviá-lo.','Only known commands and blocks are simulated. There is no real file access or PowerShell execution; clicking an example fills the field, which must then be submitted.'),steps:[
 s('Em “Terminal de consulta”, selecione e envie Get-Location e Get-ChildItem. Depois envie Set-Location logs e repita a localização.','In “Inspection terminal”, select and submit Get-Location and Get-ChildItem. Then submit Set-Location logs and repeat the location check.','A pasta atual muda, os arquivos não são movidos. Um nome relativo usa essa pasta como base; o caminho absoluto continua indicando sua base explícita.','The current folder changes; files are not moved. A relative name uses this folder as its base; an absolute path retains its explicit base.'),
 s('Use o exemplo Get-Content com -LiteralPath para access [review].txt. Depois envie Select-String com DENIED e -SimpleMatch. Compare leitura completa e linhas filtradas.','Use the Get-Content -LiteralPath example for access [review].txt. Then submit Select-String with DENIED and -SimpleMatch. Compare full reading with filtered lines.','LiteralPath preserva os colchetes como parte do nome; SimpleMatch procura o texto literal. O filtro destaca linhas, mas não conclui sozinho que todas as operações da sessão falharam.','LiteralPath preserves brackets as name characters; SimpleMatch searches literal text. Filtering highlights lines but does not alone establish that every session operation failed.'),
 s('Em “Montador de script”, monte definir arquivo → ler → anunciar sucesso e simule. Desmarque “Arquivo existe” e simule outra vez. Depois experimente anunciar antes de ler.','In “Script builder”, assemble define file → read → announce success and simulate. Clear “File exists” and simulate again. Then try announcing before reading.','Com arquivo presente e ordem correta, a leitura vem antes do sucesso. Ausência segue o erro; anúncio antecipado não comprova a leitura. Confira a trilha das etapas, não apenas a última mensagem.','With a present file and correct order, reading precedes success. Absence follows the error path; an early announcement does not prove reading. Check the stage trace, not just the last message.') ]},
 m12:{objective:b('Separar aba, sessão, autorização do app e token emitido, e escolher acessos pela finalidade e pelo destinatário.','Separate tab, session, app grant and issued token, and choose access by purpose and audience.'),limit:b('Estados e verificações são fornecidos. Nenhum cookie, conta ou JWT real é acessado; efeitos de logout e revogação variam entre serviços.','States and verification results are supplied. No actual cookie, account or JWT is accessed; logout and revocation effects vary by service.'),steps:[
 s('Em “Sessão”, reinicie o exemplo, feche e reabra a aba fictícia. Depois use “Sair do serviço fictício”. Compare os quatro cartões.','In “Session”, reset, close and reopen the fictional tab. Then sign out of the fictional service. Compare all four cards.','Fechar muda a aba, não encerra a sessão neste modelo. Sair encerra a sessão, mas deixa concessão e token emitido como estados separados.','Closing changes the tab, not the session in this model. Signing out ends the session but leaves the grant and issued token as separate states.'),
 s('Reinicie e revogue a autorização fictícia. Observe o access token; depois simule sua expiração. Qual ação impede renovação e qual encerra o token já emitido?','Reset and revoke fictional authorization. Observe the access token, then simulate its expiry. Which action prevents renewal, and which ends the already issued token?','Revogar encerra a concessão; neste modelo impede renovação, mas não apaga o token vigente. A expiração encerra esse token. Dados já copiados ficam fora desses controles.','Revocation ends the grant; here it prevents renewal but does not erase a live token. Expiration ends that token. Already copied data remains outside these controls.'),
 s('Em “Tokens”, compare cartões de ID, refresh e access. Para calendar-api · calendar.read, confira também destinatário, prazo e verificação fictícia antes de escolher.','In “Tokens”, compare ID, refresh and access cards. For calendar-api · calendar.read, also check audience, lifetime and supplied verification before choosing.','Só a finalidade access não basta: todas as condições do recurso precisam combinar. Decodificar um JWT real não produziria automaticamente o resultado “verificação aprovada”.','Access purpose alone is insufficient: every resource condition must match. Decoding a real JWT would not automatically produce a passing verification.'),
 s('Em “Permissões do app”, leia a tarefa e marque só os escopos necessários. Confira, acrescente um acesso extra e confira novamente.','In “App permissions”, read the task and select only necessary scopes. Check, add an extra permission and check again.','A comparação inclui falta e excesso. Um app que só consulta não precisa criar ou apagar. Este quadro escolhe escopos; a revogação é praticada na aba Sessão.','Comparison includes both missing and excessive access. A viewing-only app does not need create or delete. This board selects scopes; revocation is practiced in the Session tab.') ]},
 m13:{objective:b('Calcular o raciocínio de DMARC por rota: aprovação e alinhamento, sem confundir autenticação do domínio com segurança do conteúdo.','Reason about DMARC per route: pass and alignment, without confusing domain authentication with content safety.'),limit:b('Domínios organizacionais e resultados são fornecidos; não há DNS ou validação criptográfica. Os controles modificam o teste abaixo, não reescrevem a narrativa original do caso.','Organizational domains and results are supplied; there is no DNS or cryptographic validation. Controls modify the test below rather than rewriting the case’s original narrative.'),steps:[
 s('Selecione “O aviso da biblioteca”. Confira From e as duas rotas. Desative SPF e depois reative-o, mantendo DKIM reprovado.','Select “The library notice”. Check From and both routes. Disable SPF, then re-enable it while keeping DKIM failed.','SPF aprovado e alinhado basta neste caso. Quando essa única rota válida falha, DMARC falha. Não é preciso que SPF e DKIM aprovem ao mesmo tempo.','Passing aligned SPF suffices here. When this sole valid route fails, DMARC fails. SPF and DKIM do not both need to pass simultaneously.'),
 s('Compare “O convite encaminhado” e “O nome conhecido, outra origem”. Antes de alterar controles, identifique quais domínios realmente alinham com From.','Compare “The forwarded invitation” and “Familiar name, different origin”. Before changing controls, identify which domains actually align with From.','O convite usa DKIM válido e alinhado apesar da falha SPF. No outro aviso, ambos passam para relay.example, mas nenhum alinha; dois passes não bastam.','The invitation uses valid aligned DKIM despite SPF failure. In the other notice, both pass for relay.example but neither aligns; two passes are insufficient.'),
 s('No boletim do subdomínio, troque os alinhamentos estritos para relaxados, um por vez. Veja quando uma rota passa e compare política none com reject.','For the subdomain newsletter, change strict alignments to relaxed one at a time. Observe when a route passes and compare none with reject policy.','Relaxado aceita o domínio organizacional fornecido; estrito exige igualdade exata. A política muda a orientação de tratamento, não a fórmula nem os resultados de autenticação.','Relaxed accepts the supplied organizational domain; strict needs an exact match. Policy changes handling guidance, not the formula or authentication results.'),
 s('Selecione “Duas rotas consistentes”. Se o conteúdo pedisse sua senha, o DMARC aprovado seria suficiente para obedecer? Diga como confirmaria a ação.','Select “Two consistent routes”. If its content asked for your password, would passing DMARC suffice to comply? Explain how you would verify the action.','Não. Origem de domínio autenticada não prova boa intenção ou autorização do pedido. Use canal previamente conhecido e não forneça senha ou código.','No. Authenticated domain origin does not prove good intent or request authorization. Use a previously known channel and do not supply passwords or codes.') ]},
 m14:{objective:b('Limitar o compartilhamento por identidade, ação e prazo e entender quais responsabilidades mudam entre serviços de nuvem.','Limit sharing by identity, action and lifetime and understand which responsibilities change between cloud services.'),limit:b('Um arquivo e uma concessão, sem grupos ou herança. O relógio é fictício; encerrar não remove cópias baixadas. A matriz de responsabilidades é simplificada.','One file and one grant without groups or inheritance. The clock is fictional; ending access does not remove downloaded copies. The responsibility matrix is simplified.'),steps:[
 s('Em “Compartilhar e testar”, comece com a configuração aberta. Teste leitura como visitante. Depois escolha destinatários identificados, selecione só Orion e teste visitante outra vez.','In “Share and test”, start with the open configuration. Test reading as visitor. Then choose named recipients, select only Orion and test visitor again.','Saber o link deixa de bastar quando a concessão exige uma identidade selecionada. Confirme Orion permitido e visitante bloqueado; não use somente a lista de destinatários como prova.','Knowing the link stops being sufficient when the grant requires a selected identity. Check Orion allowed and visitor blocked; do not use the recipient list alone as proof.'),
 s('Use somente leitura e desative delegação. Teste Orion lendo e editando. Defina prazo de um dia e mude o relógio de dia 0 para após dois dias.','Use read-only access and disable delegation. Test Orion reading and editing. Set one-day expiry and move the clock from day 0 to after two days.','Leitura funciona antes do prazo; edição fica bloqueada. Após o prazo, essa concessão expira. Público, papel e tempo são condições separadas que precisam combinar.','Reading works before expiry; editing is blocked. After the deadline this grant expires. Audience, role and time are separate conditions that must match.'),
 s('Volte ao dia 0 e encerre a concessão. Compare Orion com Nova, a dona. Em seguida abra “Responsabilidades” e compare SaaS, PaaS e IaaS.','Return to day 0 and end the grant. Compare Orion with Nova, the owner. Then open “Responsibilities” and compare SaaS, PaaS and IaaS.','Orion perde esse acesso, mas a dona mantém o seu. Na matriz, camadas operadas mudam entre modelos; dados e decisões de identidade continuam exigindo cuidado do cliente.','Orion loses this access but the owner retains hers. In the matrix, operated layers change between models; data and identity decisions still require customer care.') ]},
 m15:{objective:b('Permitir a tarefa do portal sem abrir conversas extras e distinguir conexão nova de retorno com estado reconhecido.','Enable the portal task without opening extra conversations and distinguish new connections from state-recognized return traffic.'),limit:b('Seis fluxos TCP fixos, sem pacotes reais, NAT ou ordem de ACLs. Remover uma regra também remove o estado neste modelo; firewalls reais podem ter outros comportamentos.','Six fixed TCP flows without real packets, NAT or ACL ordering. Removing a rule also removes state here; real firewalls may behave differently.'),steps:[
 s('Leia o mapa aberto e use “Exemplo: portal interno”. Confira quais setas continuam permitidas. Explique a função de Equipe → Portal e Portal → Dados.','Read the open map and use “Example: internal portal”. Check which arrows remain allowed. Explain the role of Staff → Portal and Portal → Data.','Esses fluxos atendem ao portal interno com banco. Os demais são bloqueados por padrão. A política precisa preservar o serviço necessário e limitar os caminhos extras.','These flows serve the internal portal with a database. Others are denied by default. Policy must preserve the necessary service while limiting extra paths.'),
 s('Em “Fluxo de teste”, selecione um permitido e um bloqueado como conexão nova. Depois retire um fluxo necessário e repita seu teste.','In “Test flow”, select an allowed and a blocked new connection. Then remove a necessary flow and repeat its test.','Permissão depende da regra exata. Retirar um fluxo necessário também quebra a finalidade: reduzir risco não significa impedir indiscriminadamente todas as conversas.','Permission depends on the exact rule. Removing a necessary flow also breaks the purpose: reducing risk does not mean indiscriminately preventing every conversation.'),
 s('Restaure o portal interno, selecione um fluxo permitido e “Retorno da conexão selecionada”. Compare reconhecimento de estado desligado e ligado. Depois teste retorno de um fluxo bloqueado.','Restore the internal portal, choose an allowed flow and “Return of selected connection”. Compare state recognition off and on. Then test return for a blocked flow.','Retorno só passa com conexão autorizada e estado reconhecido. Marcar reconhecimento não cria uma conexão permitida onde a regra a nega, nem abre novas conversas no sentido inverso.','Return passes only with an authorized connection and recognized state. Checking recognition does not create an allowed connection where a rule denies it or open new reverse-direction conversations.') ]},
 m16:{objective:b('Reconstruir uma sequência de acesso com fonte, resultado, sessão e horário, separando fatos de hipóteses e lacunas.','Reconstruct an access sequence using source, outcome, session and time while separating facts, hypotheses and gaps.'),limit:b('O conjunto é fixo e fictício. Filtrar não demonstra ausência de outros eventos; converter UTC não corrige relógios desajustados.','The dataset is fixed and fictional. Filtering does not establish absence of other events; UTC conversion does not fix inaccurate clocks.'),steps:[
 s('Filtre S42 e abra os registros. Compare senha e MFA: qual etapa foi aceita e qual impediu a conclusão do login?','Filter S42 and open records. Compare password and MFA: which stage passed and which prevented completed login?','Senha aceita com MFA falho não confirma uma sessão autenticada neste caso. Relate cada resultado sem transformar a primeira etapa em acesso completo.','An accepted password with failed MFA does not establish an authenticated session here. Report each result without turning the first stage into complete access.'),
 s('Filtre S43 e acompanhe autenticação, exportação negada e leitura permitida. Ative a comparação em UTC e confira o mesmo instante nas representações.','Filter S43 and follow authentication, denied export and allowed read. Enable UTC comparison and check the same instant across representations.','Uma sessão pode ter operações com resultados diferentes. 09:01 UTC−03 e 12:01 UTC representam o mesmo instante; normalizar ajuda a ordenar registros de fontes diferentes.','A session can have operations with different outcomes. 09:01 UTC−03 and 12:01 UTC represent one instant; normalization helps order records from different sources.'),
 s('Volte a todos os registros e compare S99. Formule três frases: um fato sobre S43, uma hipótese que exige investigação e uma informação que falta.','Return to all records and compare S99. Form three statements: a fact about S43, a hypothesis needing investigation and a missing piece of information.','A exportação negada é um fato limitado à operação registrada. Intenção e identidade da pessoa precisam de mais evidência. Outros registros podem pertencer a outra sessão, mesmo com IP parecido.','The denied export is a fact limited to the recorded operation. Intent and personal identity need more evidence. Other records may belong to another session even with a similar IP.') ]},
 m17:{objective:b('Investigar execuções pelo contexto e configurar um serviço que faça seu trabalho sem alcançar recursos desnecessários.','Investigate executions by context and configure a service to do its job without reaching unnecessary resources.'),limit:b('São retratos e permissões simplificados. Administração permite todas as quatro ações no modelo; nenhum processo, conta ou serviço real é inspecionado.','These are simplified snapshots and permissions. Administration allows all four actions in the model; no real process, account or service is inspected.'),steps:[
 s('No retrato “Mesmo nome, outro contexto”, compare PID 520 com a outra execução de mesmo nome. Abra “Entender contexto” e confira conta, pai e finalidade.','In “Same name, different context”, compare PID 520 with the other same-named execution. Open “Explain context” and check account, parent and purpose.','O nome é apenas uma pista; execuções distintas podem ter contextos diferentes. A divergência de finalidade orienta investigação, sem provar malware só por PID, nome ou CPU.','A name is only a clue; distinct executions may have different contexts. Purpose discrepancies guide investigation without proving malware from PID, name or CPU alone.'),
 s('No serviço, mantenha conta administrativa e desmarque os acessos. Observe se isso realmente limita as quatro ações. Depois troque para a conta dedicada.','For the service, keep the administrative account and clear permissions. Observe whether that actually limits the four actions. Then switch to the dedicated account.','A administração ignora os seletores neste modelo e mantém acesso amplo. A conta dedicada aplica as permissões escolhidas; sem as necessárias, a tarefa também deixa de funcionar.','Administration ignores toggles here and retains broad access. The dedicated account applies selected permissions; without necessary ones the task also stops working.'),
 s('Com conta dedicada, marque ler pedidos e gravar relatórios; deixe ler notas desligado. Confira todas as linhas, incluindo gravar na entrada.','With the dedicated account, enable read requests and write reports; leave read grades off. Check every row, including input writing.','Dois acessos necessários ficam permitidos e dois extras ficam bloqueados. O resultado correto inclui negações: bloquear notas e gravação na entrada preserva os limites da tarefa.','Two required actions are allowed and two extras denied. A correct outcome includes denials: blocking grades and input writing preserves task boundaries.') ]},
 m18:{objective:b('Avaliar documento, assinatura, identidade, confiança, finalidade e tempo separadamente, sem deixar um passe compensar outra falha.','Assess document, signature, identity, trust, purpose and time separately without letting one pass compensate for another failure.'),limit:b('Resultados e certificados são fornecidos, sem validação X.509 ou assinatura real. O dia selecionado não implementa validação histórica com carimbo de tempo.','Results and certificates are supplied without real X.509 or signature validation. The selected day does not implement historical timestamp-based validation.'),steps:[
 s('No relatório esperado e dia 5, leia todas as verificações. Marque “Alterar texto sem nova assinatura” e identifique exatamente qual resultado muda.','For the expected report on day 5, read all checks. Select “Change text without a new signature” and identify exactly which outcome changes.','A assinatura deixa de corresponder ao documento alterado. Identidade ou cadeia aprovadas não corrigem a diferença de conteúdo; desmarcar retorna ao documento original neste modelo.','The signature no longer matches the changed document. Passing identity or chain does not fix differing content; clearing returns to the original document here.'),
 s('Desmarque a alteração e compare os casos com outra identidade, cadeia não confiável e uso inadequado. Qual pergunta diferente cada verificação responde?','Clear the change and compare cases with another identity, untrusted chain and unsuitable usage. Which different question does each check answer?','Uma assinatura pode corresponder e ainda falhar na identidade esperada, na confiança ou na finalidade. A decisão precisa de todas as condições relevantes, não só do selo de correspondência.','A signature may match while expected identity, trust or purpose fails. The decision needs all relevant conditions, not merely a matching seal.'),
 s('Compare certificado vencido, revogado e estado desconhecido; mude o dia consultado. Explique por que desconhecido pede mais informação, sem afirmar que é válido ou revogado.','Compare expired, revoked and unknown-status certificates; change the checked day. Explain why unknown needs more information without claiming valid or revoked.','Prazo e revogação são controles distintos. Mudar o dia pode alterar a validade temporal, mas não resolve automaticamente outra falha. A bancada avalia estados fornecidos no dia escolhido.','Lifetime and revocation are distinct checks. Changing the day may affect temporal validity but does not automatically resolve another failure. The desk evaluates supplied states on the chosen day.') ]},
 m19:{objective:b('Verificar pedidos no servidor, comunicar falhas sem detalhes internos e registrar contexto útil sem segredos.','Validate requests at the server, communicate failures without internal details and log useful context without secrets.'),limit:b('Cinco pedidos fixos são processados por um modelo no navegador. Não há servidor, banco, API nem execução de código enviado pelo aluno.','Five fixed requests are processed by a browser model. There is no server, database, API or execution of student-submitted code.'),steps:[
 s('No pedido fora do limite, compare validação no servidor desligada e ligada. Observe tanto a mensagem quanto “Gravação”, não somente a aparência dos campos.','For the out-of-range request, compare server validation off and on. Observe both the message and Write, not just field appearance.','Sem validação, o modelo aceita quantidade inválida; com ela, bloqueia antes de salvar. A requisição já chegou sem passar pela tela, mostrando por que a tela não é a fronteira final.','Without validation the model accepts invalid quantity; with it, rejection happens before saving. The request has already bypassed the screen, showing why the screen is not the final boundary.'),
 s('Mantenha validação ligada e compare tipo inesperado, clube não oferecido e pedido válido. Diga qual regra cada pedido atende ou viola.','Keep validation on and compare unexpected type, unoffered club and valid request. State which rule each request meets or violates.','Tipo, intervalo e opção permitida são verificações separadas. Um texto que parece número não atende ao contrato numérico; o pedido válido deve continuar funcionando.','Type, range and allowed choice are separate checks. Number-looking text does not meet the numeric contract; a valid request must continue to work.'),
 s('Selecione falha ao salvar. Ative primeiro mensagem sem detalhes internos e depois registro mínimo. Compare resposta ao aluno, gravação e registro interno.','Select save failure. Enable the message without internal details, then minimal logging. Compare student response, write and internal log.','A falha continua sendo falha; os controles mudam como ela é comunicada e registrada. A resposta não revela caminhos internos; o registro conserva contexto sem segredos.','Failure remains failure; controls change communication and recording. The response hides internal paths while the log retains context without secrets.') ]},
 m20:{objective:b('Escolher uma referência pela pergunta e atualizar a análise somente quando uma nova evidência realmente sustenta a conclusão.','Choose a reference by the question and update analysis only when new evidence actually supports the conclusion.'),limit:b('A bancada compara focos didáticos; não faz mapeamento automático de técnicas, auditoria, certificação ou avaliação completa de risco.','The desk compares educational focuses; it does not automatically map techniques, audit, certify or perform complete risk assessment.'),steps:[
 s('Sem registro de execução, leia o caso. Em “Pergunta da equipe”, escolha entender comportamento e compare ATT&CK com NIST CSF. Leia exemplo e limite.','Without execution evidence, read the case. Under Team question choose behavior analysis and compare ATT&CK with NIST CSF. Read example and limitation.','ATT&CK organiza comportamento; CSF organiza resultados e responsabilidades de risco. Ambos podem contribuir, mas o foco principal da pergunta é que orienta a escolha.','ATT&CK organizes behavior; CSF organizes risk outcomes and responsibilities. Both can contribute, but the question’s primary focus guides selection.'),
 s('Troque a pergunta para fases, responsabilidades e verificação do portal. Compare Kill Chain, NIST CSF e OWASP respectivamente, sem decorar uma resposta única para todo caso.','Change the question to phases, responsibilities and portal verification. Compare Kill Chain, NIST CSF and OWASP respectively instead of memorizing one answer for every case.','Kill Chain organiza fases; CSF ajuda a comunicar risco e responsáveis; OWASP oferece referências para aplicações. Um requisito de teste exige evidência além do nome da referência.','Kill Chain organizes phases; CSF helps communicate risk and ownership; OWASP provides application references. A testing requirement needs evidence beyond a reference’s name.'),
 s('Acrescente o registro de execução relacionado ao anexo. Compare a conclusão antes e depois. Quais partes da história ainda não foram demonstradas?','Add execution evidence linked to the attachment. Compare conclusions before and after. Which parts of the story remain unproven?','A execução passa a ter suporte no registro. Isso não confirma automaticamente todas as fases, saída de dados ou autoria. Nova evidência amplia apenas a conclusão que ela sustenta.','Execution now has record support. That does not automatically confirm all phases, data leaving or attribution. New evidence expands only the conclusion it supports.') ]},
 m21:{objective:b('Priorizar a fila por contexto e impacto, verificar o escopo de uma autorização e reconhecer falta de visibilidade.','Prioritize the queue by context and impact, verify authorization scope and recognize missing visibility.'),limit:b('Três alertas e uma autorização são fictícios. Não há SIEM ou coleta real; a prioridade segue a política didática da NEXUS.','Three alerts and one authorization are fictional. There is no actual SIEM or collection; priority follows NEXUS educational policy.'),steps:[
 s('Abra A01 com a autorização ainda não verificada. Leia conta, horário, recurso e operação. O rótulo de severidade basta para encerrar ou declarar incidente?','Open A01 with authorization still unverified. Read account, time, resource and operation. Is severity enough to close it or declare an incident?','Não. O alerta mostra uma correspondência e precisa de contexto. Sem verificação, dizer que a cópia foi autorizada seria uma hipótese tratada como certeza.','No. The alert shows a match and needs context. Without verification, declaring the copy authorized would treat a hypothesis as certainty.'),
 s('Verifique a autorização completa de A01 e compare a análise. Abra A02 mantendo a verificação ligada: o mesmo chamado explica sua operação?','Verify full A01 authorization and compare analysis. Open A02 while leaving verification on: does the same ticket explain its operation?','A autorização explica a cópia de materiais dentro do escopo fornecido. Ela não justifica A02. Use privilégio, recurso e comportamento inesperado para decidir onde investigar primeiro.','Approval explains the materials copy within the supplied scope. It does not justify A02. Use privilege, resource and unexpected behavior to decide what to investigate first.'),
 s('Abra A03 e compare silêncio do sensor com ausência de incidentes. Formule uma passagem com fato, lacuna e próxima verificação.','Open A03 and compare sensor silence with absence of incidents. Form a handoff with fact, gap and next check.','A falta de comunicação limita a cobertura; zero alertas não confirma segurança. A próxima ação é verificar saúde, conectividade, período e fontes alternativas, sem inventar um ataque.','Missing communication limits coverage; zero alerts does not confirm safety. Next check health, connectivity, period and alternative sources without inventing an attack.') ]},
 m22:{objective:b('Ajustar a regra para exportações inesperadas, preservando cobertura e registrando ruído, perdas e casos sem dados suficientes.','Tune the rule for unexpected exports while preserving coverage and recording noise, misses and insufficient-data cases.'),limit:b('Cinco casos e resultados esperados são fornecidos. Não executa Sigma, YARA ou Suricata; “não avaliável” é uma convenção desta bancada.','Five cases and expected outcomes are supplied. It does not execute Sigma, YARA or Suricata; “not evaluable” is this desk’s convention.'),steps:[
 s('Restaure a regra ampla e escolha a referência para logs estruturados. Leia R1–R5 antes de ajustar. Registre mentalmente acertos, ruído, perdas e lacunas.','Restore the broad rule and choose the reference for structured logs. Read R1–R5 before tuning. Note hits, noise, misses and gaps.','Sigma corresponde à fonte. A regra ampla encontra três exportações inesperadas e a autorizada R1: três acertos e um ruído. R3 é login e fica fora do objetivo.','Sigma fits the source. The broad rule finds three unexpected exports and approved R1: three hits and one noise. R3 is login and outside the goal.'),
 s('Exclua somente a autorização verificada. Compare R1 e as exportações inesperadas. Por que isso é diferente de excluir toda a conta?','Exclude only verified approval. Compare R1 and unexpected exports. Why does this differ from excluding an entire account?','R1 deixa de alertar; os três alvos continuam encontrados. A exceção acompanha a atividade aprovada, em vez de esconder outros comportamentos da mesma conta.','R1 stops alerting while all three targets remain found. The exception follows approved activity rather than hiding other behavior from the same account.'),
 s('Mantenha a exceção e exija conta administrativa. Compare R4 e R5; depois retire esse requisito e confira a recuperação da cobertura.','Keep the exception and require an administrative account. Compare R4 and R5; then remove that requirement and check coverage recovery.','R4 é alvo não administrativo e vira perda; R5 não informa o campo e vira lacuna. A regra ficou mais estreita, mas o objetivo incluía ambos. Menos alertas não prova melhora.','R4 is a nonadministrative target and becomes a miss; R5 lacks the field and becomes a gap. The rule narrowed, but the goal included both. Fewer alerts does not prove improvement.'),
 s('Desligue a coleta. Leia os cinco resultados e depois religue. Repita a configuração com exceção específica, sem exigir administração, e compare com sua base.','Disable collection. Read all five results, then re-enable it. Repeat the specific exception without requiring administration and compare against your baseline.','Sem coleta os cinco casos ficam sem avaliação, não comprovadamente seguros. Ao religar e repetir, você testa regressão: os casos anteriores precisam continuar coerentes com o objetivo.','Without collection all five cases become unevaluated, not demonstrably safe. Re-enabling and repeating tests regression: previous cases must remain consistent with the goal.') ]}
};
